import React from 'react';
import Root from './index';
import singleSpaReact from 'single-spa-react';
import { createRoot } from 'react-dom/client';
import { getAuthUser, hasValidAuthToken } from '@linm-soft-org/linm-web-common-components';
import { reconcileActiveCompanyForUser } from './utils/reconcileActiveCompany';
import { installTenantHeaderInterceptor } from './utils/installTenantHeaderInterceptor';
import { syncActiveCompanyFromJwt } from './utils/activeCompanyValidate';
import './styles/global.css';

// Embedded: validate storage vs JWT before React / apiClient fetch.
if (typeof window !== 'undefined') {
  installTenantHeaderInterceptor();
  if (hasValidAuthToken()) {
    syncActiveCompanyFromJwt();
    reconcileActiveCompanyForUser(getAuthUser());
  }
}

const setAppHeight = () =>
  document.documentElement.style.setProperty('--app-height', `${window.innerHeight}px`);
if (!CSS.supports('height', '100dvh')) {
  setAppHeight();
  window.addEventListener('resize', setAppHeight);
  window.addEventListener('orientationchange', setAppHeight);
}

const lifecycles = singleSpaReact({
  React,
  ReactDOMClient: { createRoot },
  rootComponent: Root as any,
  errorBoundary(_error: Error, _info: React.ErrorInfo, _props: unknown) {
    return (
      <div style={{ padding: '2rem', color: '#c62828' }}>
        <h2>Lỗi ứng dụng Sự cố Y Khoa</h2>
        <button onClick={() => window.location.reload()}>Tải lại</button>
      </div>
    );
  },
  renderType: 'createRoot',
});

export const { bootstrap, mount, unmount } = lifecycles;
