import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import {
  IncidentPublicReport,
  IncidentPublicReportFilters,
  IncidentPublicReportStats,
} from '../../models/IncidentPublicReport';
import { incidentPublicReportService } from '../../services/incidentPublicReports';

interface IncidentPublicReportsState {
  items: IncidentPublicReport[];
  selected: IncidentPublicReport | null;
  filters: IncidentPublicReportFilters;
  loading: boolean;
  saving: boolean;
  error: string | null;
  stats: IncidentPublicReportStats;
  pagination: { page: number; pageSize: number; totalCount: number };
}

const initialState: IncidentPublicReportsState = {
  items: [],
  selected: null,
  filters: {},
  loading: false,
  saving: false,
  error: null,
  stats: { total: 0, submitted: 0, confirmed: 0, rejected: 0 },
  pagination: { page: 1, pageSize: 20, totalCount: 0 },
};

export const fetchIncidentPublicReports = createAsyncThunk(
  'incidentPublicReports/fetchList',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as { incidentPublicReports: IncidentPublicReportsState };
    const { filters, pagination } = state.incidentPublicReports;
    return incidentPublicReportService.getList(filters, pagination.page, pagination.pageSize);
  },
);

export const fetchIncidentPublicReportStats = createAsyncThunk(
  'incidentPublicReports/fetchStats',
  async () => incidentPublicReportService.getStats(),
);

export const fetchIncidentPublicReportById = createAsyncThunk(
  'incidentPublicReports/fetchById',
  async (id: string) => incidentPublicReportService.getById(id),
);

export const confirmIncidentPublicReport = createAsyncThunk(
  'incidentPublicReports/confirm',
  async (id: string) => incidentPublicReportService.confirm(id),
);

export const rejectIncidentPublicReport = createAsyncThunk(
  'incidentPublicReports/reject',
  async ({ id, reason }: { id: string; reason: string }) =>
    incidentPublicReportService.reject(id, reason),
);

export const deleteIncidentPublicReport = createAsyncThunk(
  'incidentPublicReports/delete',
  async (id: string) => {
    await incidentPublicReportService.delete(id);
    return id;
  },
);

const applyItem = (s: IncidentPublicReportsState, item: IncidentPublicReport) => {
  const idx = s.items.findIndex((i) => i.id === item.id);
  if (idx >= 0) s.items[idx] = item;
  if (s.selected?.id === item.id) s.selected = item;
};

const incidentPublicReportsSlice = createSlice({
  name: 'incidentPublicReports',
  initialState,
  reducers: {
    setFilters(state, action: PayloadAction<IncidentPublicReportFilters>) {
      state.filters = action.payload;
      state.pagination.page = 1;
    },
    setPage(state, action: PayloadAction<number>) {
      state.pagination.page = action.payload;
    },
    setSelectedPublicReport(state, action: PayloadAction<IncidentPublicReport | null>) {
      state.selected = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchIncidentPublicReports.pending, (s) => { s.loading = true; s.error = null; })
      .addCase(fetchIncidentPublicReports.fulfilled, (s, a) => {
        s.loading = false;
        s.items = a.payload.items;
        s.pagination.totalCount = a.payload.total;
        s.pagination.page = a.payload.page;
      })
      .addCase(fetchIncidentPublicReports.rejected, (s, a) => {
        if (a.meta.aborted) return;
        s.loading = false;
        s.error = a.error.message ?? 'error';
      });

    builder.addCase(fetchIncidentPublicReportStats.fulfilled, (s, a) => { s.stats = a.payload; });

    builder
      .addCase(fetchIncidentPublicReportById.pending, (s) => { s.loading = true; s.error = null; })
      .addCase(fetchIncidentPublicReportById.fulfilled, (s, a) => {
        s.loading = false;
        s.selected = a.payload;
      })
      .addCase(fetchIncidentPublicReportById.rejected, (s, a) => {
        s.loading = false;
        s.error = a.error.message ?? 'error';
      });

    builder
      .addCase(confirmIncidentPublicReport.pending, (s) => { s.saving = true; })
      .addCase(confirmIncidentPublicReport.fulfilled, (s) => { s.saving = false; })
      .addCase(confirmIncidentPublicReport.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'error';
      });

    builder
      .addCase(rejectIncidentPublicReport.pending, (s) => { s.saving = true; })
      .addCase(rejectIncidentPublicReport.fulfilled, (s, a) => {
        s.saving = false;
        applyItem(s, a.payload);
      })
      .addCase(rejectIncidentPublicReport.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'error';
      });

    builder
      .addCase(deleteIncidentPublicReport.pending, (s) => { s.saving = true; })
      .addCase(deleteIncidentPublicReport.fulfilled, (s, a) => {
        s.saving = false;
        s.items = s.items.filter((i) => i.id !== a.payload);
        s.pagination.totalCount = Math.max(0, s.pagination.totalCount - 1);
        if (s.selected?.id === a.payload) s.selected = null;
        s.stats = {
          ...s.stats,
          total: Math.max(0, s.stats.total - 1),
        };
      })
      .addCase(deleteIncidentPublicReport.rejected, (s, a) => {
        s.saving = false;
        s.error = a.error.message ?? 'error';
      });
  },
});

export const { setFilters, setPage, setSelectedPublicReport } = incidentPublicReportsSlice.actions;
export default incidentPublicReportsSlice.reducer;
