/**
 * Real BFF endpoint calls for Medical Incident Management
 */
import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  MedicalIncident,
  MedicalIncidentFilters,
  MedicalIncidentStats,
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
  MonthlyIncidentReportDraft,
  MonthlyIncidentReportListItem,
  SaveMonthlyIncidentReportPayload,
  IncidentReportSummaryItem,
  StaffAnalysis,
  ManagementAnalysis,
  IncidentStatus,
} from '../../models/MedicalIncident';
import { expandIncidentListFilters } from '../../utils/incidentListStatusFilter';
export interface PagedResult<T> {
  items: T[];
  totalCount: number;
  total?: number; // legacy alias
  page: number;
  pageSize: number;
}

// ─── Payload sanitisation & response normalisation ────────────────────────
// The BFF DTOs have Guid? fields (departmentId, reportingDepartmentId).
// .NET System.Text.Json cannot parse an empty string "" as Guid? and throws,
// which causes the ENTIRE body to be rejected with "dto field is required".
// Always convert empty-string / zero-GUID fields to null before sending.
//
// On the read path, BFF stores DepartmentId as a non-nullable Guid, so when
// no department is selected it comes back as Guid.Empty (all-zeros).
// Normalise these back to '' so Select dropdowns match the blank option (value='').

const GUID_FIELDS: (keyof MedicalIncident)[] = ['departmentId', 'reportingDepartmentId', 'reportedById'];

/** Guid.Empty — returned by BFF for non-nullable Guid columns with no value set. */
const ZERO_GUID = '00000000-0000-0000-0000-000000000000';

function sanitizePayload(data: Partial<MedicalIncident>): Record<string, unknown> {
  const payload: Record<string, unknown> = { ...data };
  for (const field of GUID_FIELDS) {
    if (payload[field] === '' || payload[field] === ZERO_GUID) payload[field] = null;
  }
  return payload;
}

/**
 * Normalise a BFF response: convert Guid.Empty → '' so Select dropdowns can
 * match the blank option whose value is ''.
 */
function normalizeIncident(incident: MedicalIncident): MedicalIncident {
  return {
    ...incident,
    departmentId:
      incident.departmentId === ZERO_GUID ? '' : incident.departmentId,
    reportingDepartmentId:
      incident.reportingDepartmentId === ZERO_GUID ? '' : incident.reportingDepartmentId,
    reportedById:
      incident.reportedById === ZERO_GUID ? '' : incident.reportedById,
    attachments: incident.attachments ?? [],
  };
}

export const medicalIncidentEndpoint = {
  getList: async (
    filters: MedicalIncidentFilters,
    page: number,
    pageSize: number,
  ): Promise<PagedResult<MedicalIncident>> => {
    const apiFilters = expandIncidentListFilters(filters);
    const params = new URLSearchParams({
      page: String(page),
      pageSize: String(pageSize),
      ...(apiFilters.search       && { search:       apiFilters.search       }),
      ...(apiFilters.status       && { status:        apiFilters.status       }),
      ...(apiFilters.severity     && { severity:      apiFilters.severity     }),
      ...(apiFilters.reportingDepartmentId && { reportingDepartmentId: apiFilters.reportingDepartmentId }),
      ...(apiFilters.reportType          && { reportType:         apiFilters.reportType          }),
      ...(apiFilters.dateFrom            && { dateFrom:           apiFilters.dateFrom            }),
      ...(apiFilters.dateTo              && { dateTo:             apiFilters.dateTo              }),
      ...(apiFilters.isServiceMismatch != null && { isServiceMismatch: String(apiFilters.isServiceMismatch) }),
      ...(apiFilters.isNotMedicalIncident != null && { isNotMedicalIncident: String(apiFilters.isNotMedicalIncident) }),
      ...(apiFilters.hasFall           != null && { hasFall:           String(apiFilters.hasFall)           }),
    });
    const res = await apiClient.get<BffResponse<PagedResult<MedicalIncident>>>(
      `/medical-incidents?${params}`,
    );
    return unwrap(res);
  },

  getStats: async (filters?: { isServiceMismatch?: boolean; hasFall?: boolean; reportingDepartmentId?: string; dateFrom?: string; dateTo?: string }): Promise<MedicalIncidentStats> => {
    const params = new URLSearchParams();
    if (filters?.isServiceMismatch != null) params.set('isServiceMismatch', String(filters.isServiceMismatch));
    if (filters?.hasFall != null)           params.set('hasFall',           String(filters.hasFall));
    if (filters?.reportingDepartmentId)     params.set('reportingDepartmentId', filters.reportingDepartmentId);
    if (filters?.dateFrom)                  params.set('dateFrom',          filters.dateFrom);
    if (filters?.dateTo)                    params.set('dateTo',            filters.dateTo);
    const qs = params.toString();
    const res = await apiClient.get<BffResponse<MedicalIncidentStats>>(
      `/medical-incidents/stats${qs ? `?${qs}` : ''}`,
    );
    return unwrap(res);
  },

  getById: async (id: string): Promise<MedicalIncident | null> => {
    const res = await apiClient.get<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}`,
    );
    const data = unwrap(res);
    return data ? normalizeIncident(data) : null;
  },

  create: async (data: Partial<MedicalIncident>): Promise<MedicalIncident> => {
    const res = await apiClient.post<BffResponse<MedicalIncident>>(
      '/medical-incidents',
      sanitizePayload(data),
    );
    return normalizeIncident(unwrap(res));
  },

  update: async (id: string, data: Partial<MedicalIncident>): Promise<MedicalIncident> => {
    const res = await apiClient.put<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}`,
      sanitizePayload(data),
    );
    return normalizeIncident(unwrap(res));
  },

  delete: async (id: string): Promise<void> => {
    await apiClient.delete(`/medical-incidents/${id}`);
  },

  startAnalysis: async (id: string): Promise<MedicalIncident> => {
    const res = await apiClient.post<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/start-analysis`,
      {},
    );
    return normalizeIncident(unwrap(res));
  },

  submitAnalysis: async (id: string): Promise<MedicalIncident> => {
    const res = await apiClient.post<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/submit-analysis`,
      {},
    );
    return normalizeIncident(unwrap(res));
  },

  submitFeedback: async (id: string, rating: number, feedback: string): Promise<MedicalIncident> => {
    const res = await apiClient.post<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/submit-feedback`,
      { rating, feedback },
    );
    return normalizeIncident(unwrap(res));
  },

  toggleServiceMismatch: async (id: string, isServiceMismatch: boolean): Promise<MedicalIncident> => {
    const res = await apiClient.post<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/toggle-service-mismatch`,
      { isServiceMismatch },
    );
    return normalizeIncident(unwrap(res));
  },

  toggleNotMedicalIncident: async (id: string, isNotMedicalIncident: boolean): Promise<MedicalIncident> => {
    const res = await apiClient.post<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/toggle-not-medical-incident`,
      { isNotMedicalIncident },
    );
    return normalizeIncident(unwrap(res));
  },

  saveAnalysis: async (
    id: string,
    staffAnalysis: StaffAnalysis | null,
    managementAnalysis: ManagementAnalysis | null,
  ): Promise<MedicalIncident> => {
    const res = await apiClient.put<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/analysis`,
      { staffAnalysis, managementAnalysis },
    );
    return normalizeIncident(unwrap(res));
  },

  saveStaffAnalysis: async (
    id: string,
    staffAnalysis: StaffAnalysis,
  ): Promise<MedicalIncident> => {
    const res = await apiClient.put<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/staff-analysis`,
      { staffAnalysis },
    );
    return normalizeIncident(unwrap(res));
  },

  saveManagementAnalysis: async (
    id: string,
    managementAnalysis: ManagementAnalysis,
  ): Promise<MedicalIncident> => {
    const res = await apiClient.put<BffResponse<MedicalIncident>>(
      `/medical-incidents/${id}/management-analysis`,
      { managementAnalysis },
    );
    return normalizeIncident(unwrap(res));
  },

  /** Given a list of legacyIds (MSSC), returns those that already exist in the DB. */
  checkLegacyIds: async (legacyIds: string[]): Promise<string[]> => {
    if (legacyIds.length === 0) return [];
    const res = await apiClient.post<{ data: { existingIds: string[] }; success: boolean }>(
      '/medical-incidents/check-legacy-ids',
      { legacyIds },
    );
    return res.data?.existingIds ?? [];
  },

  // ── Monthly report draft (Tab 6 print form) ────────────────────────────────

  /** Paginated list of all saved monthly reports. */
  getMonthlyReportList: async (
    page = 1,
    pageSize = 20,
    search?: string,
  ): Promise<{ items: MonthlyIncidentReportListItem[]; totalCount: number; page: number; pageSize: number }> => {
    const params = new URLSearchParams({ page: String(page), pageSize: String(pageSize) });
    if (search) params.set('search', search);
    const res = await apiClient.get<BffResponse<{ items: MonthlyIncidentReportListItem[]; totalCount: number; page: number; pageSize: number }>>(
      `/medical-incidents/monthly-reports/list?${params}`,
    );
    return unwrap(res);
  },

  /** Get a specific monthly report by ID. */
  getMonthlyReportById: async (id: string): Promise<MonthlyIncidentReportDraft | null> => {
    const res = await apiClient.get<BffResponse<MonthlyIncidentReportDraft>>(
      `/medical-incidents/monthly-reports/${id}`,
    );
    return unwrap(res) ?? null;
  },

  /** Load saved draft for a period. Returns null when no draft saved yet. */
  loadMonthlyReport: async (dateFrom: string, dateTo: string): Promise<MonthlyIncidentReportDraft | null> => {
    const params = new URLSearchParams({ dateFrom, dateTo });
    const res = await apiClient.get<BffResponse<MonthlyIncidentReportDraft>>(
      `/medical-incidents/monthly-reports?${params}`,
    );
    return unwrap(res) ?? null;
  },

  /** Per-incident summary rows for Section 1 table: Khoa | Sự cố | Nguyên nhân. */
  getReportSummary: async (
    dateFrom: string,
    dateTo: string,
    includeDraft = false,
  ): Promise<IncidentReportSummaryItem[]> => {
    const params = new URLSearchParams({ dateFrom, dateTo });
    if (includeDraft) params.set('includeDraft', 'true');
    const res = await apiClient.get<BffResponse<IncidentReportSummaryItem[]>>(
      `/medical-incidents/report-summary?${params}`,
    );
    return unwrap(res);
  },

  /** Upsert monthly report draft. */
  saveMonthlyReport: async (payload: SaveMonthlyIncidentReportPayload): Promise<MonthlyIncidentReportDraft> => {
    const res = await apiClient.put<BffResponse<MonthlyIncidentReportDraft>>(
      '/medical-incidents/monthly-reports',
      payload,
    );
    return unwrap(res);
  },

  /** Submit (finalize) monthly report — transitions from Draft to Submitted. */
  submitMonthlyReport: async (payload: SaveMonthlyIncidentReportPayload): Promise<MonthlyIncidentReportDraft> => {
    const res = await apiClient.post<BffResponse<MonthlyIncidentReportDraft>>(
      '/medical-incidents/monthly-reports/submit',
      { ...payload, action: 'Submit' },
    );
    return unwrap(res);
  },

  /** Delete a monthly report by ID. */
  deleteMonthlyReport: async (id: string): Promise<void> => {
    await apiClient.delete(`/medical-incidents/monthly-reports/${id}`);
  },

  /** Approve a submitted report. */
  approveMonthlyReport: async (id: string): Promise<MonthlyIncidentReportDraft> => {
    const res = await apiClient.post<BffResponse<MonthlyIncidentReportDraft>>(
      `/medical-incidents/monthly-reports/${id}/approve`,
    );
    return unwrap(res);
  },

  /** Cancel a submitted report (revert to Draft). */
  cancelMonthlyReport: async (id: string): Promise<MonthlyIncidentReportDraft> => {
    const res = await apiClient.post<BffResponse<MonthlyIncidentReportDraft>>(
      `/medical-incidents/monthly-reports/${id}/cancel`,
    );
    return unwrap(res);
  },

  getReport: async (filters: MedicalIncidentReportFilters): Promise<MedicalIncidentReport> => {
    const params = new URLSearchParams();
    if (filters.search)      params.set('search',      filters.search);
    if (filters.year)         params.set('year',         String(filters.year));
    if (filters.dateFrom)     params.set('dateFrom',     filters.dateFrom);
    if (filters.dateTo)       params.set('dateTo',       filters.dateTo);
    if (filters.reportingDepartmentId) params.set('reportingDepartmentId', filters.reportingDepartmentId);
    if (filters.includeDraft) params.set('includeDraft', 'true');
    const res = await apiClient.get<BffResponse<MedicalIncidentReport>>(
      `/medical-incidents/reports?${params}`,
    );
    return unwrap(res);
  },

  /** Fetch all incident IDs matching filters (paginates until complete). */
  getAllIds: async (filters: MedicalIncidentFilters): Promise<string[]> => {
    const pageSize = 200;
    const ids: string[] = [];
    let page = 1;
    let totalCount = 0;

    do {
      const result = await medicalIncidentEndpoint.getList(filters, page, pageSize);
      totalCount = result.totalCount ?? result.total ?? 0;
      ids.push(...result.items.map((item) => item.id));
      page += 1;
    } while (ids.length < totalCount);

    return ids;
  },

  /** Update the status of multiple incidents in one call. */
  batchUpdateStatus: async (ids: string[], status: IncidentStatus): Promise<MedicalIncident[]> => {
    const res = await apiClient.patch<BffResponse<MedicalIncident[]>>(
      '/medical-incidents/batch-status',
      { ids, status },
    );
    return unwrap(res).map(normalizeIncident);
  },

  /** Export all incidents matching filters to an .xlsx file returned as Blob. */
  exportAll: async (filters: MedicalIncidentFilters): Promise<Blob> => {
    const apiFilters = expandIncidentListFilters(filters);
    const body = {
      ...(apiFilters.status            && { status:            apiFilters.status            }),
      ...(apiFilters.severity          && { severity:          apiFilters.severity          }),
      ...(apiFilters.reportingDepartmentId && { reportingDepartmentId: apiFilters.reportingDepartmentId }),
      ...(apiFilters.reportType        && { reportType:        apiFilters.reportType        }),
      ...(apiFilters.search            && { search:            apiFilters.search            }),
      ...(apiFilters.isServiceMismatch != null && { isServiceMismatch: apiFilters.isServiceMismatch }),
      ...(apiFilters.isNotMedicalIncident != null && { isNotMedicalIncident: apiFilters.isNotMedicalIncident }),
      ...(apiFilters.hasFall           != null && { hasFall:           apiFilters.hasFall           }),
      ...(apiFilters.dateFrom          && { dateFrom:          apiFilters.dateFrom          }),
      ...(apiFilters.dateTo            && { dateTo:            apiFilters.dateTo            }),
    };
    return apiClient.postBlob('/medical-incidents/export', body);
  },
};
