import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import { guestBff } from './guestClient';
import type {
  IncidentPublicReport,
  IncidentPublicReportFilters,
  IncidentPublicReportGuestInit,
  IncidentPublicReportPoster,
  IncidentPublicReportStats,
} from '../../models/IncidentPublicReport';

export interface PagedResult<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

const mapPage = (data: {
  items: IncidentPublicReport[];
  totalCount: number;
  page: number;
  pageSize: number;
}): PagedResult<IncidentPublicReport> => ({
  items: data.items,
  total: data.totalCount,
  page: data.page,
  pageSize: data.pageSize,
});

export const incidentPublicReportEndpoint = {
  guestInit: (companyCode: string): Promise<IncidentPublicReportGuestInit> =>
    guestBff(companyCode, 'GET', `/incident-public-reports/guest-init?companyCode=${encodeURIComponent(companyCode)}`),

  submit: (companyCode: string, payload: Record<string, unknown>): Promise<IncidentPublicReport> =>
    guestBff(companyCode, 'POST', '/incident-public-reports', payload),

  mine: (companyCode: string, page = 1, pageSize = 20): Promise<PagedResult<IncidentPublicReport>> =>
    guestBff<{
      items: IncidentPublicReport[];
      totalCount: number;
      page: number;
      pageSize: number;
    }>(companyCode, 'GET', `/incident-public-reports/mine?companyCode=${encodeURIComponent(companyCode)}&page=${page}&pageSize=${pageSize}`)
      .then(mapPage),

  mineById: (companyCode: string, id: string): Promise<IncidentPublicReport> =>
    guestBff(companyCode, 'GET', `/incident-public-reports/mine/${id}?companyCode=${encodeURIComponent(companyCode)}`),

  getList: async (
    filters: IncidentPublicReportFilters,
    page: number,
    pageSize: number,
  ): Promise<PagedResult<IncidentPublicReport>> => {
    const params = new URLSearchParams({
      page: String(page),
      pageSize: String(pageSize),
      ...(filters.search && { search: filters.search }),
      ...(filters.status && { status: filters.status }),
      ...(filters.departmentId && { departmentId: filters.departmentId }),
    });
    const res = await apiClient.get<BffResponse<{
      items: IncidentPublicReport[];
      totalCount: number;
      page: number;
      pageSize: number;
    }>>(`/incident-public-reports?${params}`);
    return mapPage(unwrap(res));
  },

  getStats: async (): Promise<IncidentPublicReportStats> => {
    const res = await apiClient.get<BffResponse<IncidentPublicReportStats>>('/incident-public-reports/stats');
    return unwrap(res);
  },

  getById: async (id: string): Promise<IncidentPublicReport | null> => {
    const res = await apiClient.get<BffResponse<IncidentPublicReport>>(`/incident-public-reports/${id}`);
    return unwrap(res);
  },

  confirm: async (id: string): Promise<{ id: string; idCode?: string }> => {
    const res = await apiClient.post<BffResponse<{ id: string; idCode?: string }>>(
      `/incident-public-reports/${id}/confirm`,
    );
    return unwrap(res);
  },

  reject: async (id: string, reason: string): Promise<IncidentPublicReport> => {
    const res = await apiClient.post<BffResponse<IncidentPublicReport>>(
      `/incident-public-reports/${id}/reject`,
      { reason },
    );
    return unwrap(res);
  },

  delete: async (id: string): Promise<void> => {
    await apiClient.delete(`/incident-public-reports/${id}`);
  },

  poster: async (): Promise<IncidentPublicReportPoster> => {
    const res = await apiClient.get<BffResponse<IncidentPublicReportPoster>>('/incident-public-reports/poster');
    return unwrap(res);
  },
};
