import { appSettings } from '../../config/appSettings';
import { getClientTimezone } from '../../utils/dateTime';
import { getOrCreatePublicDeviceId } from '../../utils/publicDeviceId';
import type { BffResponse } from '../shared/bffEnvelope';
import { unwrap } from '../shared/bffEnvelope';

const DEVICE_HEADER = 'X-Device-Id';

function baseUrl(): string {
  return appSettings.apiUrl.replace(/\/$/, '');
}

function guestHeaders(companyCode: string, extra?: Record<string, string>): HeadersInit {
  return {
    Accept: 'application/json',
    'Content-Type': 'application/json',
    'X-Company-Id': companyCode.trim().toUpperCase(),
    [DEVICE_HEADER]: getOrCreatePublicDeviceId(),
    'X-Timezone': getClientTimezone(),
    ...extra,
  };
}

function readMessage(json: unknown, fallback: string): string {
  if (!json || typeof json !== 'object') return fallback;
  const row = json as { message?: unknown; error?: { message?: unknown } };
  if (typeof row.message === 'string' && row.message.trim()) return row.message.trim();
  if (typeof row.error?.message === 'string' && row.error.message.trim()) return row.error.message.trim();
  return fallback;
}

export async function guestBffBlob(companyCode: string, path: string): Promise<Blob> {
  const response = await fetch(`${baseUrl()}${path}`, {
    method: 'GET',
    credentials: 'omit',
    headers: {
      Accept: '*/*',
      'X-Company-Id': companyCode.trim().toUpperCase(),
      [DEVICE_HEADER]: getOrCreatePublicDeviceId(),
      'X-Timezone': getClientTimezone(),
    },
  });
  if (!response.ok) {
    const json = await response.json().catch(() => ({}));
    throw Object.assign(new Error(readMessage(json, 'Chưa tìm thấy file trên storage (chưa PUT hoặc đã xóa).')), {
      statusCode: response.status,
    });
  }
  return response.blob();
}

async function guestBffResponse(
  companyCode: string,
  method: 'GET' | 'POST',
  path: string,
  body?: unknown,
): Promise<{ ok: boolean; status: number; json: unknown }> {
  const response = await fetch(`${baseUrl()}${path}`, {
    method,
    credentials: 'omit',
    headers: guestHeaders(companyCode),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await response.text();
  let json: unknown = {};
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = {};
    }
  }
  return { ok: response.ok, status: response.status, json };
}

function throwGuestBffError(status: number, json: unknown): never {
  if (status === 429) {
    throw new Error(readMessage(json, 'Bạn gửi quá nhiều lần. Vui lòng thử lại sau 1 phút.'));
  }
  if (status === 409) {
    throw new Error(readMessage(json, 'Thiết bị này đã gửi phiếu tương tự trong 24 giờ.'));
  }
  throw new Error(readMessage(json, 'Hệ thống lỗi vui lòng thử lại sau'));
}

export async function guestBff<T>(
  companyCode: string,
  method: 'GET' | 'POST',
  path: string,
  body?: unknown,
): Promise<T> {
  const { ok, status, json } = await guestBffResponse(companyCode, method, path, body);
  if (!ok) throwGuestBffError(status, json);
  return unwrap(json as BffResponse<T>);
}

export async function guestBffOk(
  companyCode: string,
  method: 'POST',
  path: string,
  body?: unknown,
): Promise<void> {
  const { ok, status, json } = await guestBffResponse(companyCode, method, path, body);
  if (!ok) throwGuestBffError(status, json);
}
