import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { navigateInAppPath, type InAppNavigateFn } from '../routing/navigateInAppPath';

/** In-app SCYK navigation — shell URL bar sync via navigateInAppPath. */
export function useAppNavigate() {
  const navigate = useNavigate();
  return useCallback(
    (path: string, options?: { replace?: boolean }) =>
      navigateInAppPath(path, navigate as InAppNavigateFn, options),
    [navigate],
  );
}
