import { useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { isStandalone } from '../dev/isStandalone';
import { LINM_NAV_FORCE_PATH_EVENT } from './navigateInAppPath';

/**
 * Keeps MemoryRouter aligned with the browser address bar.
 * - Embedded: window → memory (single-spa nav, back/forward)
 * - Standalone: memory → window via replaceState (paste/F5/copy link)
 *
 * Shell mode: memory → window disabled — @linm/nav owns URL via navigateToUrl.
 * Leave guard runs in StandaloneMockNav / @linm/nav forceShellNavigate — not here
 * (wrapping sync here caused window↔memory ping-pong in standalone).
 */
export const MemoryRouterSync: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const locationRef = useRef(location);
  locationRef.current = location;

  const syncingFromWindowRef = useRef(false);

  useEffect(() => {
    const syncFromWindow = () => {
      const next = window.location.pathname + window.location.search;
      const current =
        locationRef.current.pathname + locationRef.current.search;
      if (next === current) return;
      syncingFromWindowRef.current = true;
      navigate(next, { replace: true });
    };

    const forceMenuPath = (e: Event) => {
      if (isStandalone) return;
      const detail = (e as CustomEvent<{ path?: string; exact?: boolean }>).detail;
      const path = detail?.path;
      if (!path) return;
      const next = detail?.exact || path.includes('?')
        ? path
        : path + window.location.search;
      const current =
        locationRef.current.pathname + locationRef.current.search;
      if (next === current) return;
      syncingFromWindowRef.current = true;
      navigate(next, { replace: true });
    };

    window.addEventListener('single-spa:routing-event', syncFromWindow);
    window.addEventListener('popstate', syncFromWindow);
    window.addEventListener(LINM_NAV_FORCE_PATH_EVENT, forceMenuPath);
    // Shell only — standalone mount sync fights `<Navigate to="/dev" />`.
    if (!isStandalone) {
      syncFromWindow();
    }
    return () => {
      window.removeEventListener('single-spa:routing-event', syncFromWindow);
      window.removeEventListener('popstate', syncFromWindow);
      window.removeEventListener(LINM_NAV_FORCE_PATH_EVENT, forceMenuPath);
    };
  }, [navigate]);

  useEffect(() => {
    if (!isStandalone) return;
    if (syncingFromWindowRef.current) {
      syncingFromWindowRef.current = false;
      return;
    }

    const next = location.pathname + location.search;
    const current = window.location.pathname + window.location.search;
    if (next !== current) {
      window.history.replaceState(null, '', next);
    }
  }, [location.pathname, location.search]);

  return null;
};

/** @deprecated Use MemoryRouterSync */
export const RouterSync = MemoryRouterSync;

export default MemoryRouterSync;
