import {
  getSecureItem,
  removeSecureItem,
  setSecureItem,
  type SecureStorageConfig,
} from '@linm-soft-org/linm-web-common-components';

const SIDEBAR_KEY = 'sidebar-collapsed-preference';

const CONFIG: SecureStorageConfig = {
  storageKey: SIDEBAR_KEY,
  version: 1,
  hashKey: 'ui.sidebar',
};

export function getSidebarCollapsed(): boolean {
  const val = getSecureItem<string>(CONFIG, { allowLegacyPlain: true });
  return val === 'collapsed';
}

export function setSidebarCollapsed(collapsed: boolean): void {
  setSecureItem(CONFIG, collapsed ? 'collapsed' : 'expanded');
}
